CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), display_name text NOT NULL DEFAULT '', contact_email text, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL CHECK(provider IN ('google','apple')), issuer text NOT NULL, subject text NOT NULL, email text, email_verified boolean NOT NULL DEFAULT false, UNIQUE(provider,issuer,subject));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_hash text UNIQUE NOT NULL, user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, staff_step_up_at timestamptz, revoked_at timestamptz);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE oauth_transactions (state_hash text PRIMARY KEY, cookie_hash text NOT NULL, provider text NOT NULL, nonce text NOT NULL, verifier text NOT NULL, link_user_id uuid REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE staff_roles(user_id uuid REFERENCES users(id), role text CHECK(role IN ('owner','admin','editor','publisher','concierge','fulfillment','finance')), PRIMARY KEY(user_id,role));
CREATE TABLE staff_factors(id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), public_key bytea NOT NULL, counter bigint NOT NULL, transports jsonb NOT NULL DEFAULT '[]');
CREATE TABLE staff_challenges(session_id uuid PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, challenge text NOT NULL, purpose text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE bootstrap_state(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), used_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE staff_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, roles jsonb NOT NULL, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, accepted_by uuid REFERENCES users(id), revoked_at timestamptz);

-- One revision engine for products, collections, posts, pages, videos, site settings and templates.
CREATE TABLE content_entities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('products','collections','journal','pages','videos','site-config','email-templates','locations')), slug text NOT NULL, lifecycle text NOT NULL DEFAULT 'active' CHECK(lifecycle IN ('active','archived')), live_revision_id uuid, preview_revision_id uuid, version integer NOT NULL DEFAULT 0, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,slug));
CREATE TABLE content_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid NOT NULL REFERENCES content_entities(id), revision_number integer NOT NULL, schema_version integer NOT NULL DEFAULT 1, content jsonb NOT NULL, seo jsonb NOT NULL DEFAULT '{}', created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(entity_id,revision_number), UNIQUE(entity_id,id));
ALTER TABLE content_entities ADD FOREIGN KEY(id,live_revision_id) REFERENCES content_revisions(entity_id,id), ADD FOREIGN KEY(id,preview_revision_id) REFERENCES content_revisions(entity_id,id);
CREATE INDEX content_live ON content_entities(kind,id) WHERE live_revision_id IS NOT NULL AND lifecycle='active';
CREATE TABLE revision_products(revision_id uuid REFERENCES content_revisions(id), product_id uuid REFERENCES content_entities(id), position integer NOT NULL, PRIMARY KEY(revision_id,product_id));
CREATE TABLE product_variants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES content_entities(id), sku text UNIQUE NOT NULL, title text NOT NULL, price_minor bigint CHECK(price_minor>=0), currency text NOT NULL DEFAULT 'INR', active boolean NOT NULL DEFAULT true);
CREATE TABLE preview_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_hash text NOT NULL UNIQUE, entity_id uuid NOT NULL, revision_id uuid NOT NULL, created_by uuid REFERENCES users(id), expires_at timestamptz NOT NULL, revoked_at timestamptz, require_reviewer_login boolean NOT NULL DEFAULT false, FOREIGN KEY(entity_id,revision_id) REFERENCES content_revisions(entity_id,id));
CREATE TABLE preview_sessions(token_hash text PRIMARY KEY, link_id uuid NOT NULL REFERENCES preview_links(id), expires_at timestamptz NOT NULL);
CREATE TABLE publication_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid NOT NULL REFERENCES content_entities(id), from_revision_id uuid, to_revision_id uuid, action text NOT NULL, actor_id uuid REFERENCES users(id), occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, entity_id text, changes jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only record'; END $$;
CREATE TRIGGER immutable_revision BEFORE UPDATE OR DELETE ON content_revisions FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER immutable_publication BEFORE UPDATE OR DELETE ON publication_events FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TABLE redirects(source_path text PRIMARY KEY, target_path text NOT NULL, status integer NOT NULL CHECK(status IN (301,308)), enabled boolean NOT NULL DEFAULT true);
CREATE TABLE scheduled_publications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid NOT NULL REFERENCES content_entities(id), revision_id uuid NOT NULL, expected_version integer NOT NULL, publish_at timestamptz NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), status text NOT NULL DEFAULT 'queued', FOREIGN KEY(entity_id,revision_id) REFERENCES content_revisions(entity_id,id));
CREATE TABLE media_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), storage_key text UNIQUE NOT NULL, mime_type text NOT NULL, bytes bigint NOT NULL CHECK(bytes>0 AND bytes<=104857600), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','quarantined','ready','rejected')), uploaded_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE revision_media(revision_id uuid REFERENCES content_revisions(id), media_id uuid REFERENCES media_assets(id), PRIMARY KEY(revision_id,media_id));
CREATE TABLE carts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), guest_hash text UNIQUE, state text NOT NULL DEFAULT 'active', expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days', CHECK((user_id IS NULL) <> (guest_hash IS NULL)));
CREATE UNIQUE INDEX active_user_cart ON carts(user_id) WHERE state='active';
CREATE TABLE cart_items(cart_id uuid REFERENCES carts(id) ON DELETE CASCADE, variant_id uuid REFERENCES product_variants(id), quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 99), PRIMARY KEY(cart_id,variant_id));
CREATE TABLE saved_rituals(user_id uuid REFERENCES users(id), product_id uuid REFERENCES content_entities(id), PRIMARY KEY(user_id,product_id));
CREATE TABLE consultation_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), full_name text NOT NULL, email text NOT NULL, phone text NOT NULL, location text NOT NULL, preferred_date date NOT NULL, preferred_window text NOT NULL, focus_label text NOT NULL, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','scheduled','cancelled','completed')), assigned_to uuid REFERENCES users(id), version integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX consultation_status ON consultation_requests(status,created_at,id);
CREATE TABLE consultation_private_notes(request_id uuid PRIMARY KEY REFERENCES consultation_requests(id), ciphertext text NOT NULL, key_version text NOT NULL);
CREATE TABLE contact_inquiries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), name text NOT NULL, email text NOT NULL, subject text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','in_progress','resolved')), assigned_to uuid REFERENCES users(id), version integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE consent_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_reference uuid NOT NULL, purpose text NOT NULL, policy_version text NOT NULL, granted boolean NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text NOT NULL, payload jsonb NOT NULL, dedupe_key text UNIQUE, state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','completed','failed')), attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), locked_until timestamptz, lease_token uuid, last_error text, completed_at timestamptz);
CREATE INDEX jobs_claim ON jobs(available_at,id) WHERE state='queued';
CREATE INDEX jobs_lease ON jobs(locked_until) WHERE state='running';
CREATE TABLE idempotency_keys(scope text, key text, request_hash text NOT NULL, response_body jsonb NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '1 day', PRIMARY KEY(scope,key));
CREATE TABLE rate_limit_buckets(scope text, key_hash text, window_start timestamptz, count integer NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(scope,key_hash,window_start));
CREATE TABLE video_events(event_id uuid PRIMARY KEY, video_id uuid REFERENCES content_entities(id), event_type text CHECK(event_type IN ('impression','play_start','play_complete','cta_click')), received_at timestamptz NOT NULL DEFAULT now());
